from pathlib import Path
import json,datetime,re
base=Path('/mnt/ws-jfs/ycfeng/miles-qwen35-three-pairs/first-round/student/C/exp-1107-064200-013666/failure-diagnostics/rank-0')
p=base/'memory.jsonl';samples=[json.loads(x) for x in p.open()]
rows=[]
for s in samples:
 t=s['unix_time'];c=s['counters'];used=int(c['/sys/fs/cgroup/memory/memory.usage_in_bytes']);oom=c['/sys/fs/cgroup/memory/memory.oom_control']
 rows.append({'unix_time':t,'utc':datetime.datetime.fromtimestamp(t,datetime.timezone.utc).isoformat(),'bytes':used,'GiB':used/2**30,'oom_control':oom})
start=datetime.datetime.fromisoformat('2026-11-07T01:07:00+00:00').timestamp();end=datetime.datetime.fromisoformat('2026-11-07T01:12:00+00:00').timestamp()
window=[r for r in rows if start<=r['unix_time']<=end]
report={'source':str(p),'samples':len(rows),'training_sleep_window':window,'phase_points':[],'ray_memory_records':[]}
for stamp in ['2026-11-07T00:12:53+00:00','2026-11-07T00:30:00+00:00','2026-11-07T01:07:24+00:00','2026-11-07T01:08:02+00:00','2026-11-07T01:11:10+00:00','2026-11-07T01:11:29+00:00']:
 t=datetime.datetime.fromisoformat(stamp).timestamp();r=min(rows,key=lambda r:abs(r['unix_time']-t));report['phase_points'].append({'requested_utc':stamp,**r})
pattern=re.compile(r'out of memory|oom|OutOfMemory|killed due|memory pressure|memory usage|memory monitor|SIGKILL',re.I)
for p in base.glob('*'):
 if p.name=='memory.jsonl' or not p.is_file():continue
 for i,line in enumerate(p.open(errors='replace'),1):
  if pattern.search(line):report['ray_memory_records'].append({'file':p.name,'line_number':i,'text':line[:1400].strip()})
print(json.dumps(report))
